mapper.select:
SELECT template_id AS templateId,COUNT(*) AS totalCount,
  COALESCE(SUM(send_status='COPIED'),0) AS copiedCount,
  COALESCE(SUM(send_status='SDK_SUCCESS'),0) AS successCount,
  COALESCE(SUM(send_status='SDK_FAILED'),0) AS failedCount,
  COALESCE(SUM(send_status='SDK_UNKNOWN'),0) AS unknownCount,
  COALESCE(SUM(edited=1),0) AS editedCount,
  COUNT(DISTINCT employee_id) AS employeeCount,MAX(send_time) AS lastUsedAt
FROM crm_quick_reply_usage
WHERE tenant_id=#{tenantId}
 AND employee_id=#{employeeId}
 AND send_time >=#{from,jdbcType=TIMESTAMP}
 AND send_time <#{to,jdbcType=TIMESTAMP}
GROUP BY template_id
